#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

    #[verifier(spec)]
    fn concat(a: &Vec<u64>, b: &Vec<u64>) -> Vec<u64>
        // we assume both inputs are at most length 100
        requires a.len() <= 100;
        requires b.len() <= 100;
        // the resulting vector has length exactly a.len() + b.len()
        ensures ret.len() == a.len() + b.len();
        // for all i in [0, a.len()), ret[i] == a[i]
        ensures forall |i: usize|
            i < a.len() ==> ret[i] == a[i];
        // for all i in [a.len(), ret.len()), ret[i] == b[i - a.len()]
        ensures forall |i: usize|
            a.len() <= i && i < ret.len() ==>
                ret[i] == b[i - a.len()];
    {
        let mut ret: Vec<u64> = Vec::new();

        // First, append all elements of `a`.
        let mut i: usize = 0;
        while i < a.len() {
            invariant i <= a.len();
            invariant ret.len() == i;
            invariant forall |k: usize| k < i ==> ret[k] == a[k];
            decreases a.len() - i;
            {
                ret.push(a[i]);
                i += 1;
            }
        }

        // Next, append all elements of `b`.
        let mut j: usize = 0;
        while j < b.len() {
            invariant j <= b.len();
            invariant ret.len() == a.len() + j;
            invariant forall |k: usize| k < a.len() ==> ret[k] == a[k];
            invariant forall |k: usize|
                a.len() <= k && k < a.len() + j ==>
                    ret[k] == b[k - a.len()];
            decreases b.len() - j;
            {
                ret.push(b[j]);
                j += 1;
            }
        }

        ret
    }

}